"""Build the complete static edition. Python 3.10+, standard library only."""
from pathlib import Path
import json,re,html,math
ROOT=Path(__file__).resolve().parents[1]
BASE='https://auraofintelligence.github.io/UNGA81-Luke-Hayes/'
REPO='https://github.com/auraofintelligence/UNGA81-Luke-Hayes'
PDF='documents/UNGA81_Joyful_Responsible_Abundance_Refined.pdf'
E=html.escape
PAGES=[
 ('index','A fair go in the age of intelligence','Overview','An invitation to build Joyful Responsible Abundance. A personal contribution to UNGA81 by Luke Nathan Hayes.'),
 ('invitation','Futures worth inhabiting','The invitation','Three ordinary words. A world of possible meanings. An invitation to explore what makes a good life, together.'),
 ('capability','More capability. More choice.','Shared capability','Local intelligence, peaceful cooperation and useful infrastructure. Progress that leaves people with more possibilities.'),
 ('livelihoods','A richer life, in every sense.','Livelihoods & time','Ownership, useful work, care and freedom over time. What should the productivity dividend make possible?'),
 ('intelligence','Intelligence with a human centre.','Personal & civic intelligence','Personal agency, voluntary reflection and a democracy people can understand and help shape.'),
 ('futures','A garland of possible futures.','GAJRA Earth','Locally rooted, globally connected. A proposed process for turning shared questions into practical work.'),
 ('library','Follow the ideas to their sources.','Reference library','The document, its 29 reference entries and a growing collection of connected public work.'),
 ('about','An open invitation. A clear foundation.','About & site map','The author, the original document, the site map and the terms for sharing and using this work.')]
CONTENT=json.loads((ROOT/'data/content.json').read_text(encoding='utf-8'))
REFS=json.loads((ROOT/'data/references.json').read_text(encoding='utf-8'))
ALT={
 'index':'Imagined garden islands linked by flowing bridges around a luminous sphere, in a calm sunlit sea.',
 'invitation':'A garland of distinct coral, yellow, white, turquoise and lilac flowers suspended above water.',
 'capability':'An imagined coastal computing pavilion beside greenhouses, gardens and pools connected by warm-water channels.',
 'livelihoods':'A joyful imagined neighbourhood with a workshop, garden, shared table and a golden wheel marking time.',
 'intelligence':'Separate transparent spheres containing gardens and community spaces, connected by delicate pathways.',
 'futures':'Three colourful arches in a coastal amphitheatre where people gather among flowers.',
 'library':'Sculptural books and paper-like terraces surrounding a turquoise pool and a coral arch.',
 'about':'An eight-petalled sculptural flower at the centre of connected garden paths.'}
def slug(s):return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def link(url,label,cls=''):return f'<a href="{E(url,quote=True)}"'+(f' class="{cls}"' if cls else '')+f'>{E(label)}</a>'
def picture(key,cls='',lazy=False):
 return f'<img class="{cls}" src="assets/images/{key}-1536.webp" srcset="assets/images/{key}-768.webp 768w, assets/images/{key}-1536.webp 1536w" sizes="(max-width: 760px) 100vw, 92vw" width="1536" height="1024" alt="{E(ALT[key])}" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+' decoding="async">'
MARK='<img class="brand-mark" src="assets/brand-garland.png" width="42" height="42" alt="">'

def hero(key,title,desc):
 if key=='index':
  return f'''<section class="home-intro wrap"><div><h1>A fair go in the<br>age of <em>intelligence.</em></h1></div><div class="intro-note"><p class="lead">An invitation to build<br><strong>Joyful Responsible Abundance.</strong></p><p>Define futures worth inhabiting.<br>Make room for everyone to help build them.</p><a class="button" href="invitation.html">Read the invitation <span aria-hidden="true">↗</span></a></div></section><figure class="hero-art wrap home-art">{picture(key)}<figcaption><span>Distinct communities. Connected possibilities.</span><span>AI-generated concept illustration</span></figcaption></figure><div class="byline wrap"><span>A personal contribution to UNGA81</span><span>Luke Nathan Hayes · Minjerribah, Australia · September 2026</span></div>'''
 return f'''<section class="page-intro wrap"><h1>{E(title)}</h1><p class="lead">{E(desc)}</p></section><figure class="hero-art wrap">{picture(key)}<figcaption>AI-generated concept illustration. An imagined possibility.</figcaption></figure>'''
def home():
 cards=''.join(f'<a class="chapter-card" href="{key}.html"><div class="card-art">{picture(key,lazy=True)}<span class="circle-arrow" aria-hidden="true">↗</span></div><div class="card-copy"><span class="chapter-number">0{i}</span><h3>{E(label)}</h3><p>{E(desc)}</p></div></a>' for i,(key,title,label,desc) in enumerate(PAGES[1:6],1))
 return f'''<section class="compass-section wrap" aria-labelledby="compass-title"><div class="section-heading"><h2 id="compass-title">Three words.<br><em>Held together.</em></h2><p>A compass for experiments, comparisons and corrections. Explore each word, then ask what changes when we hold them together.</p></div><div class="compass"><div class="compass-controls" aria-label="Explore the three words"><button class="compass-button joyful" data-word="joyful" aria-pressed="true">Joyful <span aria-hidden="true">✳</span></button><button class="compass-button responsible" data-word="responsible" aria-pressed="false">Responsible <span aria-hidden="true">◎</span></button><button class="compass-button abundance" data-word="abundance" aria-pressed="false">Abundance <span aria-hidden="true">✺</span></button></div><div class="compass-answer" aria-live="polite"><p id="compass-question">Did life become more worth living?</p><p id="compass-detail">Relationships, curiosity, belonging, creativity, music, travel, laughter, rest and time to enjoy them.</p><a class="text-link" href="invitation.html#a-three-part-compass">Read the full three-part compass <span aria-hidden="true">↗</span></a></div></div><noscript><p>Responsible: did we take responsibility for the consequences? Abundance: did useful capability become more abundant and more widely shared?</p></noscript></section><section class="wrap journey" id="explore"><div class="section-heading"><h2>A future with<br><em>more ways in.</em></h2><p>Follow the contribution from its opening invitation to practical possibilities. Read in order, or start with the question that matters to you.</p></div><div class="chapter-grid">{cards}<a class="library-card" href="library.html"><span class="big-flower" aria-hidden="true">✳</span><h3>Go to the source.</h3><p>The original eight-page PDF, 29 reference entries and links to the work behind the ideas.</p><span class="text-link">Explore the library ↗</span></a></div></section><section class="quote-panel wrap"><blockquote>“A gajra is a flower garland. The flowers remain distinct when connected.”</blockquote><p>From the invitation</p><a class="button pale" href="futures.html">Explore GAJRA Earth <span aria-hidden="true">↗</span></a></section><section class="source-strip wrap"><div><h2>One contribution.<br>An ongoing conversation.</h2><p>This is an independent personal contribution, with proposals to explore and sources to examine. It is not a United Nations publication or endorsement.</p></div><a class="button outline" href="{PDF}">Open the original PDF <span aria-hidden="true">↗</span></a></section>'''
RELATED={'invitation':[1,2,3,4,5,6,20,29],'capability':[7,8,9,10,11,17,18,19],'livelihoods':[12,13,14,21,22,23,24,25],'intelligence':[26,27,28],'futures':[15,16,29]}
def chapter(key):
 secs=CONTENT[key];toc=''.join(link('#'+slug(s['title']),s['title']) for s in secs)
 article='';words=0
 for sec in secs:
  blocks=sec['blocks'];article+=f'<section class="reading-section" id="{slug(sec["title"])}"><h2>{E(sec["title"])}</h2>'
  if sec['title']=='Health and everyday access':article+='<aside class="editorial-note"><strong>Reading note</strong> This passage describes the author’s proposed research. It does not establish that the suggested approaches remove toxins or provide a proven treatment.</aside>'
  i=0
  while i<len(blocks):
   b=blocks[i];words+=len(b['text'].split())
   if b['type']=='li':
    ordered=bool(re.match(r'^\d+\.',b['text']));tag='ol' if ordered else 'ul';article+=f'<{tag}>'
    while i<len(blocks) and blocks[i]['type']=='li':
     t=re.sub(r'^(?:•|\d+\.)\s*','',blocks[i]['text']);article+=f'<li data-source="true">{E(t)}</li>';i+=1
    article+=f'</{tag}>';continue
   article+=f'<p data-source="true">{E(b["text"])}</p>';i+=1
  article+='</section>'
 related=''.join(link(f'library.html#ref-{n}',f'{n:02d} · '+REFS[n-1]['title'],'reference-pill') for n in RELATED[key])
 return f'''<div class="reading-layout wrap"><aside class="contents"><details open><summary>On this page</summary><nav aria-label="On this page">{toc}</nav></details><p>{max(1,math.ceil(words/210))} minute read · Original text</p><a class="text-link" href="{PDF}">Original PDF ↗</a></aside><article class="prose">{article}<section class="related" aria-labelledby="related-title"><h2 id="related-title">Follow the sources</h2><p>Reference numbers match the register in the original PDF.</p><div class="reference-links">{related}</div></section></article></div>'''
def library():
 cards=''
 for r in REFS:
  n=r['id'];links=''.join(link(x['url'],x['label']+' ↗','text-link') for x in r['links'])
  cards+=f'''<article class="reference-card" id="ref-{n}" data-category="{E(r['category'])}" data-status="{E(r['status'])}"><div class="ref-top"><span class="ref-number">{n:02d}</span><span class="status {'pending' if r['status'].startswith('Awaiting') else ''}">{E(r['status'])}</span></div><h3>{E(r['title'])}</h3><p class="source-description" data-source="true">{E(r['description'])}</p>{f'<p class="reference-note">{E(r["note"])}</p>' if r['note'] else ''}<div class="source-links">{links}</div><a class="permalink" href="#ref-{n}" aria-label="Permanent link to reference {n}">#{n:02d}</a></article>'''
 return f'''<section class="document-feature wrap"><div><h2>The original contribution.</h2><p>A fair go in the age of intelligence<br>An invitation to build Joyful Responsible Abundance</p><p>Luke Nathan Hayes · September 2026 · 8 pages</p><a class="button" href="{PDF}">Read the PDF <span aria-hidden="true">↗</span></a> <a class="text-link" href="{PDF}" download>Download a copy ↓</a></div><div class="document-cover" aria-hidden="true">{MARK}<span>A fair go<br>in the age of<br><em>intelligence.</em></span><small>Joyful Responsible Abundance<br>A personal contribution to UNGA81</small></div></section><section class="wrap library-section" id="references"><div class="section-heading"><h2>The reference library.</h2><p>All 29 entries from the document, with links added for this web edition. Source descriptions are preserved; web notes explain matches, related material and gaps.</p></div><p class="library-intro">Institutional links were identified on 21 September 2026. Connected projects link to their public pages and repositories. “Awaiting document” means the named file has not yet been added; “Partly linked” means part of an entry remains to be confirmed.</p><form class="library-tools" role="search" onsubmit="return false"><div class="search-field"><label for="reference-search">Search references</label><input id="reference-search" type="search" placeholder="Try local AI, livelihoods or GAJRA…" autocomplete="off"></div><div><label for="reference-category">Collection</label><select id="reference-category"><option value="all">All collections</option><option>Institutional sources</option><option>Author documents</option><option>Connected projects</option></select></div><div><label for="reference-status">Availability</label><select id="reference-status"><option value="all">All entries</option><option value="linked">With links</option><option value="pending">Awaiting material</option></select></div><button id="clear-filters" type="button" class="button outline">Clear</button></form><p id="result-count" role="status">{len(REFS)} references</p><noscript><p>All references are shown below. Search and filtering require JavaScript.</p></noscript><div class="reference-grid">{cards}</div><div id="empty-results" class="empty-state" hidden><h3>No matching references.</h3><p>Try another word or clear the filters to see the whole collection.</p></div></section><section class="source-strip wrap"><div><h2>A library with room to grow.</h2><p>Further papers, public links and reference documents can be added as they become available. The three named papers are available above as unchanged Word originals.</p></div><a class="button outline" href="{REPO}#adding-a-reference-document">How to add material ↗</a></section>'''
def licence_html():
 lines=(ROOT/'LICENCE.md').read_text(encoding='utf-8').splitlines();out='';lst=False
 for line in lines[1:]:
  if not line.strip():continue
  if line.startswith('- '):
   if not lst:out+='<ul>';lst=True
   out+='<li>'+E(line[2:])+'</li>';continue
  if lst:out+='</ul>';lst=False
  out+=('<h3>'+E(line[3:])+'</h3>') if line.startswith('## ') else '<p>'+E(line)+'</p>'
 if lst:out+='</ul>'
 return out
def about():
 sm=''.join(f'<a href="{k}.html"><span>{i+1:02d}</span><div><h3>{E(label)}</h3><p>{E(desc)}</p></div><span aria-hidden="true">↗</span></a>' for i,(k,t,label,desc) in enumerate(PAGES))
 return f'''<div class="about-grid wrap"><section><h2>From Minjerribah,<br>to an open question.</h2><p class="lead">Luke Nathan Hayes</p><p>Strange but True: Tech, art and ideas that'll help.<br>Minjerribah / North Stradbroke Island, Queensland, Australia.</p><p>This independent personal contribution responds to the UNGA81 theme, “Restoring Trust, Managing Transformation: A United Nations That Delivers for All”. It connects the author’s work on intelligence, ownership, livelihoods, democratic participation and possible futures.</p><p>The proposals are invitations to inquiry and practical experimentation. Their inclusion does not imply that a programme is operating, a treaty interpretation is authoritative, or an institution endorses this contribution.</p><a class="text-link" href="mailto:auraofintelligence@gmail.com">Contact Luke ↗</a></section><aside class="about-card"><h2>Keep the source close.</h2><p>The supplied PDF is preserved byte for byte. The five reading chapters reproduce its body text, with web headings, navigation and clearly separated reading notes.</p><p>The reference library retains all 29 entries. Additional links and notes belong to the web edition; missing files remain labelled.</p><a class="button" href="{PDF}">Original document ↗</a><a class="text-link" href="{REPO}">View the public repository ↗</a></aside></div><section class="wrap site-map" id="site-map"><h2>Find your way.</h2><p>Site map: every page in the reading journey.</p><nav class="map-links" aria-label="Site map">{sm}</nav></section><section class="wrap about-grid"><div><h2>Made for reading<br>and sharing.</h2><p>Each page has its own AI-generated concept illustration. These imagined places are visual interpretations, not photographs, project renders based on engineering, or evidence of completed work.</p><p>The site uses no analytics, advertising, account system or tracking cookies. Search happens in your browser. GitHub hosts the site and may process standard access logs; external links follow their own privacy terms.</p><p>The text works without JavaScript. Motion respects your device’s reduced-motion setting, and every long page has a return-to-top link. Your browser’s Print command produces a simple reading copy.</p></div><div><h2>Image provenance.</h2><p>Eight original hero images and a garland favicon were generated for this edition using OpenAI image generation on 21 September 2026, then resized and compressed for the web.</p><p>Prompts and generation details are available with the source.</p><a class="text-link" href="data/image-prompts.json">Read the hero image prompts ↗</a><br><a class="text-link" href="data/favicon-prompt.json">Read the garland favicon prompt ↗</a></div></section><section class="wrap licence-section" id="licence"><div class="section-heading"><h2>Strange But True<br>Public Source Licence.</h2><p>Personal, educational, artistic, research, community and other non-commercial uses are permitted with attribution. Commercial and institutional uses require written permission. The full terms below govern use.</p></div><a class="text-link" href="LICENCE.md">Download the licence text ↓</a><details class="licence-details"><summary>Read the full licence</summary><div class="prose">{licence_html()}</div></details></section>'''
def footer(i):
 prev=PAGES[(i-1)%len(PAGES)];nxt=PAGES[(i+1)%len(PAGES)]
 return f'''<footer class="wrap footer"><nav class="page-turns" aria-label="Previous and next pages"><a href="{prev[0]}.html"><small>← Previous</small><span>{E(prev[2])}</span></a><a href="{nxt[0]}.html"><small>Next →</small><span>{E(nxt[2])}</span></a></nav><div class="footer-base"><a class="brand" href="index.html">{MARK}<span>Joyful Responsible<br>Abundance</span></a><p>A personal contribution by Luke Nathan Hayes.<br>Strange but True · September 2026</p><nav aria-label="Footer"><a href="about.html#site-map">Site map</a><a href="about.html#licence">Licence</a><a href="{REPO}">GitHub ↗</a></nav></div></footer><a href="#top" class="back-top" aria-label="Back to top"><span aria-hidden="true">↑</span><span class="top-label">Top</span></a>'''
for i,(key,title,label,desc) in enumerate(PAGES):
 nav=''.join(f'<a href="{k}.html"'+(' aria-current="page"' if k==key else '')+f'>{E(l)}</a>' for k,t,l,d in PAGES)
 body=home() if key=='index' else library() if key=='library' else about() if key=='about' else chapter(key)
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'url':BASE+key+'.html','description':desc,'inLanguage':'en-AU','author':{'@type':'Person','name':'Luke Nathan Hayes'},'isPartOf':{'@type':'WebSite','name':'Joyful Responsible Abundance','url':BASE}}
 page=f'''<!doctype html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#fffaf0"><title>{E(title)} | Joyful Responsible Abundance</title><meta name="description" content="{E(desc,quote=True)}"><link rel="canonical" href="{BASE}{'' if key=='index' else key+'.html'}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="{BASE}{'' if key=='index' else key+'.html'}"><meta property="og:image" content="{BASE}assets/images/social.jpg"><meta property="og:image:alt" content="An imagined garland of garden islands connected by bridges"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="favicon.ico" sizes="16x16 32x32 48x48"><link rel="icon" href="assets/favicon-32.png" type="image/png" sizes="32x32"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body id="top" class="page-{key}"><a class="skip-link" href="#main">Skip to content</a><div class="reading-progress" aria-hidden="true"></div><header class="site-header wrap"><a class="brand" href="index.html" aria-label="Joyful Responsible Abundance home">{MARK}<span>Joyful Responsible<br>Abundance</span></a><nav class="desktop-nav" aria-label="Main"><a href="invitation.html" {'aria-current="page"' if key=='invitation' else ''}>The invitation</a><a href="library.html" {'aria-current="page"' if key=='library' else ''}>Reference library</a><a href="about.html" {'aria-current="page"' if key=='about' else ''}>About</a></nav><details class="site-menu"><summary>Explore <span aria-hidden="true">＋</span></summary><nav aria-label="All pages">{nav}</nav></details></header><main id="main">{hero(key,title,desc)}{body}</main>{footer(i)}</body></html>'''
 (ROOT/(key+'.html')).write_text(page,encoding='utf-8')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+('' if k=='index' else k+'.html')+'</loc></url>' for k,*_ in PAGES)+'</urlset>\n',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n',encoding='utf-8')
(ROOT/'.nojekyll').touch()
(ROOT/'404.html').write_text('<!doctype html><html lang="en-AU"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | Joyful Responsible Abundance</title><style>body{font:1.2rem/1.6 system-ui;background:#fffaf0;color:#243b33;margin:12vh auto;max-width:40rem;padding:2rem}h1{font:4rem Georgia}a{color:#13534c}</style><h1>A different path.</h1><p>This page could not be found. The invitation and the library are still here.</p><a href="'+BASE+'">Return to the homepage →</a></html>',encoding='utf-8')
print('Built 8 pages, sitemap, robots.txt and 404 page.')
